package com.yuegang.zhihui.wallet.application;import com.yuegang.zhihui.common.mq.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(name="ygh.mq.enabled",havingValue="true")class WalletOutboxConfiguration{@Bean(destroyMethod="close")DomainEventPublisher walletEventPublisher(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t){return new RocketMqDomainEventPublisher("ygh-wallet-producer",n,t);}@Bean WalletOutboxJob walletOutboxJob(JdbcTemplate j,DomainEventPublisher p){return new WalletOutboxJob(new JdbcOutboxDispatcher(j,p,"wallet_outbox"));}static final class WalletOutboxJob{private final JdbcOutboxDispatcher d;WalletOutboxJob(JdbcOutboxDispatcher d){this.d=d;}@Scheduled(fixedDelayString="${ygh.mq.dispatch-delay:1000}")public void dispatch(){d.dispatch();}}}
